"""Nonce DISGUISE of (text, formula) pairs: every content lemma -> a pronounceable nonce word, consistently in the text
AND in the predicate/constant names of the formula. Logic, quantifier and function words are untouched; arity,
argument order, variables and connectives are untouched.

Departure from the plan text (documented in README): the formula is disguised by TOKEN-LEVEL substitution of predicate
and constant identifiers in the raw string (whitespace, bracketing and symbols preserved byte-for-byte), and the result
is verified on the AST (assertion (i): the inverse name map applied to parse(disguised) == parse(original)). This keeps
the orig vs disg judge conditions identical in surface form except for the names, which is what the contamination
contrast needs; an AST re-printer would also change bracketing.
"""
from __future__ import annotations

import re
from functools import lru_cache

from .common import norm, sha1

PROTECTED = set("""all every each some any no none not never if then only unless except either or and nor both neither
is are be a an the who which that there exists also may can must does do of in on at to for with by from as than more most
least many few one two three their they it its he she his her someone something everyone everything people person thing
was were been being has have had am this these those what when where whether but so because while all anyone anything
nobody nothing somebody everybody others other another such same""".split())
CONS, VOWS = "bdfgklmnprstvz", "aeiou"
IDENT = re.compile(r"[A-Za-z_][A-Za-z0-9_'\-]*")
CAMEL = re.compile(r"[A-Z]?[a-z]+|[A-Z]+(?![a-z])|\d+")
CONTENT_POS = {"NOUN", "PROPN", "VERB", "ADJ", "ADV"}

_NLP = None
_WORDS = None
_STEM = None


def stem(w: str) -> str:
    """Canonical key for a lemma (Porter stem), so text 'engaged'/'engage' and name piece 'Engaged' share one nonce."""
    global _STEM
    if _STEM is None:
        from nltk.stem import PorterStemmer
        _STEM = PorterStemmer()
    return _STEM.stem(w.lower())


def nlp():
    global _NLP
    if _NLP is None:
        import spacy
        _NLP = spacy.load("en_core_web_sm", disable=["ner", "parser"])
    return _NLP


def english_words() -> set:
    global _WORDS
    if _WORDS is None:
        from nltk.corpus import words
        _WORDS = {w.lower() for w in words.words()}
    return _WORDS


@lru_cache(maxsize=200000)
def lemma_of_piece(piece: str) -> str:
    p = piece.lower()
    if p.isdigit() or len(p) <= 1:
        return p
    doc = nlp()(p)
    return (doc[0].lemma_ or p).lower() if len(doc) else p


def _nonce_from_int(h: int) -> str:
    out = []
    for syl in range(3):
        out.append(CONS[h % len(CONS)]); h //= len(CONS)
        out.append(VOWS[h % len(VOWS)]); h //= len(VOWS)
        if syl < 2 and h % 3 == 0:  # optional coda on the first two syllables
            h //= 3
            out.append(CONS[h % len(CONS)]); h //= len(CONS)
        else:
            h //= 3
    return "".join(out)


def nonce(lemma: str, seed_text: str, taken: set) -> str:
    k = 0
    while True:
        h = int(sha1(f"{norm(seed_text)}|{lemma}|{k}"), 16)
        w = _nonce_from_int(h)
        if w not in english_words() and w not in taken and w not in PROTECTED:
            return w
        k += 1


def split_name(name: str) -> list[str]:
    parts = []
    for chunk in re.split(r"[_\-']", name):
        parts.extend(CAMEL.findall(chunk))
    return parts or [name]


def _inflect(tok: str, lemma: str, nw: str) -> str:
    t = tok.lower()
    suf = ""
    if t != lemma and t.startswith(lemma) and t[len(lemma):] in ("s", "es", "ed", "d", "ing", "er", "r", "est", "st", "ly"):
        suf = {"d": "ed", "r": "er", "st": "est"}.get(t[len(lemma):], t[len(lemma):])
    elif t != lemma:
        for s in ("ing", "est", "ed", "er", "es", "ly", "s"):
            if t.endswith(s):
                suf = s
                break
    out = nw + suf
    if tok[:1].isupper():
        out = out[:1].upper() + out[1:]
    return out


def formula_roles(fol: str) -> list[tuple[str, str]]:
    """(identifier, role) in textual order; role in {pred, const, var}. Works on unparseable strings too."""
    ids = [m.group(0) for m in IDENT.finditer(fol)]
    # positions: an identifier followed (after spaces) by '(' is a predicate; identifier right after a quantifier symbol
    # is a variable; identifiers inside predicate argument lists are const unless bound somewhere as variable.
    roles = []
    bound = set(re.findall(r"[∀∃]\s*([a-z][a-z0-9]*)", fol))
    depth_args = 0
    pos = 0
    for m in IDENT.finditer(fol):
        name = m.group(0)
        after = fol[m.end():].lstrip()
        before = fol[:m.start()].rstrip()
        if before.endswith(("∀", "∃")):
            roles.append((name, "var"))
        elif after.startswith("("):
            roles.append((name, "pred"))
        else:
            # inside an argument list?  count unmatched '(' that belong to a predicate call
            inside = _inside_args(fol, m.start())
            if inside:
                roles.append((name, "var" if name in bound else "const"))
            else:
                roles.append((name, "pred"))  # propositional atom
        pos = m.end()
    del ids, depth_args, pos
    return roles


def _inside_args(fol: str, i: int) -> bool:
    depth, j = 0, i - 1
    while j >= 0:
        ch = fol[j]
        if ch == ")":
            depth += 1
        elif ch == "(":
            if depth == 0:
                k = j - 1
                while k >= 0 and fol[k] == " ":
                    k -= 1
                return k >= 0 and (fol[k].isalnum() or fol[k] in "_'-")
            depth -= 1
        j -= 1
    return False


def disguise_item(text: str, fol: str | None, seed_text: str | None = None) -> dict:
    """Returns {text_d, fol_d, lemma_map, name_map, ok, fail_reasons, leak_text, leak_formula}."""
    seed = seed_text if seed_text is not None else text
    doc = nlp()(text)
    lemmas = []
    for t in doc:
        lw = (t.lemma_ or t.text).lower()
        if t.pos_ in CONTENT_POS and t.text.lower() not in PROTECTED and lw not in PROTECTED and t.text.isalpha():
            lemmas.append(stem(lw))
    orig_lemmas = {(t.lemma_ or t.text).lower() for t in doc if t.pos_ in CONTENT_POS and t.text.isalpha()
                   and t.text.lower() not in PROTECTED}
    roles = formula_roles(fol) if fol else []
    for name, role in roles:
        if role in ("pred", "const"):
            for p in split_name(name):
                lp = lemma_of_piece(p)
                if lp not in PROTECTED and not lp.isdigit() and len(lp) > 1:
                    lemmas.append(stem(lp))
                    orig_lemmas.add(lp)
    lemma_map, taken = {}, set()
    for lw in sorted(set(lemmas)):
        w = nonce(lw, seed, taken)
        lemma_map[lw] = w
        taken.add(w)
    # ---- text
    out = []
    for t in doc:
        lw = (t.lemma_ or t.text).lower()
        tl = t.text.lower()
        sk = stem(lw) if t.text.isalpha() else None
        if t.text.isalpha() and tl not in PROTECTED and lw not in PROTECTED and (sk in lemma_map or stem(tl) in lemma_map):
            key = sk if sk in lemma_map else stem(tl)
            out.append(_inflect(t.text, lw, lemma_map[key]) + t.whitespace_)
        else:
            out.append(t.text_with_ws)
    text_d = "".join(out)
    # ---- formula (token-level substitution, surface form preserved)
    name_map, used = {}, {}
    fol_d = None
    if fol:
        pieces_out = []
        last = 0
        ridx = 0
        for m in IDENT.finditer(fol):
            name, role = roles[ridx]
            ridx += 1
            pieces_out.append(fol[last:m.start()])
            last = m.end()
            if role == "var":
                pieces_out.append(name)
                continue
            key = (name, role)
            if key not in name_map:
                parts = []
                for p in split_name(name):
                    lp = lemma_of_piece(p)
                    if stem(lp) in lemma_map and lp not in PROTECTED:
                        parts.append(lemma_map[stem(lp)])
                    else:
                        parts.append(p.lower())  # protected / digit piece kept
                if role == "pred":
                    new = "".join(x[:1].upper() + x[1:] for x in parts)
                else:
                    new = "".join(parts).lower()
                    if not new[:1].isalpha():
                        new = "k" + new
                base, k = new, 0
                while new in used and used[new] != key:
                    k += 1
                    new = base + ("Zo" if role == "pred" else "zo") * k
                used[new] = key
                name_map[key] = new
            pieces_out.append(name_map[key])
        pieces_out.append(fol[last:])
        fol_d = "".join(pieces_out)
    # ---- assertions
    fails = []
    if fol:
        from .labeller.fol import parse
        from .labeller.repair_census import rename
        inv_p = {}
        inv_c = {}
        for (name, role), new in name_map.items():
            (inv_p if role == "pred" else inv_c)[new] = name
        try:
            e0 = parse(fol)
            try:
                e1 = parse(fol_d)
                # inverse map on AST
                from .labeller.repair_census import symbols
                P1, _ = symbols(e1)
                pmap = {(n, a): inv_p.get(n, n) for (n, a) in P1}
                back = rename(e1, pmap, inv_c)
                if back != e0:
                    fails.append("inverse_map_ast_mismatch")
                from .labeller.fol import preds
                if sorted(preds(e0).values()) != sorted(preds(e1).values()):
                    fails.append("arity_multiset_changed")
            except Exception as ex:  # noqa: BLE001
                fails.append(f"disguised_unparseable:{str(ex)[:60]}")
        except Exception:  # noqa: BLE001 - original unparseable: disguise still applied token-wise
            pass
        new_names = list(name_map.values())
        if len(set(new_names)) != len(new_names):
            fails.append("name_collision")
    vals = list(lemma_map.values())
    if len(set(vals)) != len(vals):
        fails.append("nonce_collision")
    # protected word counts unchanged
    def pcount(s):
        toks = re.findall(r"[A-Za-z]+", s.lower())
        return sorted(t for t in toks if t in PROTECTED)
    if pcount(text) != pcount(text_d):
        fails.append("protected_count_changed")
    # leaks
    cont = {l for l in orig_lemmas if len(l) >= 4 and l not in PROTECTED}
    text_toks = {(t.lemma_ or t.text).lower() for t in nlp()(text_d)} | set(re.findall(r"[a-z]+", text_d.lower()))
    leak_t = sum(1 for l in cont if l in text_toks) / max(1, len(cont))
    leak_f = 0.0
    if fol_d:
        f_pieces = {lemma_of_piece(p) for n in IDENT.findall(fol_d) for p in split_name(n)}
        leak_f = sum(1 for l in cont if l in f_pieces) / max(1, len(cont))
        if leak_f > 0:
            fails.append("formula_leak")
    return {"text_d": text_d, "fol_d": fol_d, "lemma_map": lemma_map,
            "name_map": {f"{k[0]}|{k[1]}": v for k, v in name_map.items()}, "ok": not fails, "fail_reasons": fails,
            "leak_text": round(leak_t, 4), "leak_formula": round(leak_f, 4)}

src_files.src/labeller/fol.py:
"""Unicode FOL (FOLIO/MALLS notation) -> AST -> z3; semantic monotonicity profile per predicate.

Grammar (lowest to highest precedence): ↔  <  →  <  ∨ / ⊕  <  ∧  <  ¬, quantifiers, atoms  (⊕ fixed to bind like ∨).
A quantifier binds the immediately following parenthesised group, atom, negation or quantifier
(FOLIO/MALLS convention: '∀x (A(x)) ∧ ∀y (B(y))' is two sentences).
"""
import re
import z3

TOK = re.compile(r"\s*(∀|∃|¬|∧|∨|→|↔|⊕|\(|\)|,|[A-Za-z_][A-Za-z0-9_'\-]*)")
OPS = {"↔": "iff", "⊕": "xor", "→": "imp", "∨": "or", "∧": "and"}
PREC = {"iff": 1, "xor": 3, "imp": 2, "or": 3, "and": 4}  # FIX (iter-3 review): ⊕ binds like ∨, tighter than →


def tokenize(s: str) -> list[str]:
    s = s.replace("⇒", "→").replace("->", "→").replace("<->", "↔").replace("&", "∧").replace("|", "∨")
    s = s.replace("~", "¬").replace("!", "¬").replace("¬", "¬").replace("−", "-")
    pos, out = 0, []
    s = s.strip().rstrip(".")
    while pos < len(s):
        m = TOK.match(s, pos)
        if not m:
            raise ValueError(f"bad char at {pos}: {s[pos:pos+10]!r}")
        out.append(m.group(1))
        pos = m.end()
        while pos < len(s) and s[pos].isspace():
            pos += 1
    return out


class Parser:
    def __init__(self, s: str):
        self.t = tokenize(s)
        self.i = 0

    def peek(self):
        return self.t[self.i] if self.i < len(self.t) else None

    def eat(self, x=None):
        tok = self.peek()
        if x is not None and tok != x:
            raise ValueError(f"expected {x} got {tok}")
        self.i += 1
        return tok

    def parse(self):
        e = self.expr(0)
        if self.peek() is not None:
            raise ValueError(f"trailing {self.t[self.i:]}")
        return e

    def expr(self, minp):
        lhs = self.unary()
        while self.peek() in OPS and PREC[OPS[self.peek()]] > minp - 1 and PREC[OPS[self.peek()]] >= minp:
            op = OPS[self.eat()]
            # → is right-assoc, others left-assoc
            nxt = PREC[op] if op == "imp" else PREC[op] + 1
            rhs = self.expr(nxt)
            lhs = (op, lhs, rhs)
        return lhs

    def unary(self):
        tok = self.peek()
        if tok == "¬":
            self.eat()
            return ("not", self.unary())
        if tok in ("∀", "∃"):
            self.eat()
            vs = [self.eat()]
            while self.peek() not in ("(", "¬", "∀", "∃") and self.peek() is not None and re.match(r"^[a-z][a-z0-9]*$", self.peek() or "") and not self._is_atom_start():
                vs.append(self.eat())
            body = self.unary()  # FOLIO/MALLS convention: a quantifier binds the next group/atom/quantifier
            for v in reversed(vs):
                body = ("all" if tok == "∀" else "ex", v, body)
            return body
        if tok == "(":
            self.eat("(")
            e = self.expr(0)
            self.eat(")")
            return e
        name = self.eat()
        if self.peek() == "(":
            self.eat("(")
            args = [self.eat()]
            while self.peek() == ",":
                self.eat(",")
                args.append(self.eat())
            self.eat(")")
            return ("atom", name, tuple(args))
        return ("atom", name, ())  # propositional atom

    def _is_atom_start(self):
        return self.i + 1 < len(self.t) and self.t[self.i + 1] == "("


def parse(s: str):
    return Parser(s).parse()


def preds(e, acc=None):
    acc = {} if acc is None else acc
    if e[0] == "atom":
        acc[f"{e[1]}/{len(e[2])}"] = len(e[2])  # key by name/arity: arity clashes are distinct symbols
    elif e[0] in ("all", "ex"):
        preds(e[2], acc)
    elif e[0] == "not":
        preds(e[1], acc)
    else:
        preds(e[1], acc)
        preds(e[2], acc)
    return acc


U = z3.DeclareSort("U")


def to_z3(e, env, P):
    k = e[0]
    if k in ("all", "ex"):
        v = z3.Const(e[1], U)
        env2 = dict(env)
        env2[e[1]] = v
        b = to_z3(e[2], env2, P)
        return z3.ForAll([v], b) if k == "all" else z3.Exists([v], b)
    if k == "not":
        return z3.Not(to_z3(e[1], env, P))
    if k == "atom":
        args = [env.get(a, z3.Const("c_" + a, U)) for a in e[2]]
        f = P[f"{e[1]}/{len(e[2])}"]
        return f(*args) if args else f
    a, b = to_z3(e[1], env, P), to_z3(e[2], env, P)
    return {"and": lambda: z3.And(a, b), "or": lambda: z3.Or(a, b), "imp": lambda: z3.Implies(a, b),
            "iff": lambda: a == b, "xor": lambda: z3.Xor(a, b)}[k]()


def mkpred(name, n):
    name = name.replace("/", "_a")
    return z3.Function(name, *([U] * n), z3.BoolSort()) if n else z3.Bool(name)


def valid(c, ms=3000):
    s = z3.Solver()
    s.set("timeout", ms)
    s.add(z3.Not(c))
    r = s.check()
    return True if r == z3.unsat else (False if r == z3.sat else None)


def profile(e, ms=3000):
    """Semantic monotonicity of formula e in each predicate: UP / DOWN / VACUOUS / NONMONO / UNKNOWN."""
    ar = preds(e)
    base = {q: mkpred(q, m) for q, m in ar.items()}
    out = {}
    for p, n in ar.items():
        alt = dict(base)
        alt[p] = mkpred(p + "_prime", n)
        xs = [z3.Const(f"_x{i}", U) for i in range(n)]
        sub = z3.ForAll(xs, z3.Implies(base[p](*xs), alt[p](*xs))) if n else z3.Implies(base[p], alt[p])
        F, Fp = to_z3(e, {}, base), to_z3(e, {}, alt)
        up, down = valid(z3.Implies(z3.And(sub, F), Fp), ms), valid(z3.Implies(z3.And(sub, Fp), F), ms)
        if up is None or down is None:
            out[p] = "UNKNOWN"
        else:
            out[p] = {(True, True): "VACUOUS", (True, False): "UP", (False, True): "DOWN", (False, False): "NONMONO"}[(up, down)]
    return out


def equivalent(e1, e2, ms=5000):
    ar = {**preds(e1), **preds(e2)}
    P = {q: mkpred(q, m) for q, m in ar.items()}
    return valid(to_z3(e1, {}, P) == to_z3(e2, {}, P), ms)


def connectivity_flags(e):
    """Binding check: inside each quantifier scope, variables must be linked through shared atoms.
    Returns list of variables that are quantified but share no atom with any other variable in the
    same top-level sentence while other variables exist (an 'island')."""
    atoms = []

    def walk(x):
        if x[0] == "atom":
            atoms.append(set(a for a in x[2]))
        elif x[0] in ("all", "ex"):
            walk(x[2])
        elif x[0] == "not":
            walk(x[1])
        else:
            walk(x[1]); walk(x[2])

    def qvars(x, acc):
        if x[0] in ("all", "ex"):
            acc.append(x[1]); qvars(x[2], acc)
        elif x[0] == "not":
            qvars(x[1], acc)
        elif x[0] != "atom":
            qvars(x[1], acc); qvars(x[2], acc)
        return acc

    walk(e)
    vs = qvars(e, [])
    if len(vs) < 2:
        return []
    # union-find over variables via atoms
    parent = {v: v for v in vs}

    def f(v):
        while parent[v] != v:
            v = parent[v]
        return v
    for a in atoms:
        a = [v for v in a if v in parent]
        for v in a[1:]:
            parent[f(v)] = f(a[0])
    comps = {}
    for v in vs:
        comps.setdefault(f(v), []).append(v)
    if len(comps) == 1:
        return []
    main = max(comps.values(), key=len)
    return [v for c in comps.values() if c is not main for v in c]


def prenex_blocks(e):
    """Split a formula into top-level conjuncts; for each, collect its leading quantifier block."""
    parts = []

    def flat(x):
        if x[0] == "and":
            flat(x[1]); flat(x[2])
        else:
            parts.append(x)
    flat(e)
    return parts


def coupled_independent_vars(e):
    """GLUE check: within ONE top-level conjunct, >=2 universally quantified variables that never
    co-occur in any atom, i.e. independent generic claims wrongly bundled under a joint quantifier
    ('∀x∀y (Wolf(x) ∧ Bird(y) → Howls(x) ∧ Chirps(y))'). Returns True if any conjunct has one."""
    for part in prenex_blocks(e):
        if connectivity_flags(part):
            return True
    return False


def token_profile(prof):
    """Project a predicate-level polarity profile onto CamelCase word tokens, so that merged
    (WorksInNewsIndustryAndReportsOnEvents) and split (WorksInNewsIndustry ∧ ReportsOnEvents)
    renderings of the same concept get the same profile."""
    import re as _re
    STOP = {"and", "or", "of", "in", "on", "the", "a", "an", "to", "is", "has", "have", "can", "for", "with", "by", "at", "from"}
    out = {}
    for key, pol in prof.items():
        name = key.split("/")[0]
        for w in _re.findall(r"[A-Z]?[a-z]+|[A-Z]+(?![a-z])|\d+", name):
            w = w.lower()
            if w in STOP:
                continue
            w = w[:-1] if w.endswith("s") and len(w) > 3 else w
            out.setdefault(w, set()).add(pol)
    return out

src_files.src/labeller/labeller.py:
"""Shared-screen labeller: equivalence of a candidate FOL formula to a trusted reference MODULO VOCABULARY.

Exact sequence of iter-3 repair_census.work (equivalent -> align -> equivalent -> gran_bridge -> equivalent -> search),
wrapped as equivalent_modulo_vocab(cand, ref) -> dict. Differences from iter 3 (all logged in README):
  * fol.py PREC['xor'] = 3 (⊕ binds like ∨, tighter than →)  -- the iter-3 review bug fix;
  * the typed-repair search uses a DETERMINISTIC node budget (max level-2 candidates) instead of a wall-clock budget, so
    the label vector does not depend on machine load (a generous wall-clock guard remains and is reported if hit);
  * PYTHONHASHSEED must be fixed (the random-model fingerprint and set iteration orders use hash()); the caller
    (method.py) sets PYTHONHASHSEED=0 for every worker process.
"""
from __future__ import annotations

import re
import time

from .fol import parse, equivalent
from .repair_census import align, gran_bridge, edits, fp, toks

CORRECT_CLASSES = {"EQUIV", "VOCAB", "GRAN"}


def token_jaccard(a: str, b: str) -> float:
    ta, tb = set(toks(a)), set(toks(b))
    if not ta and not tb:
        return 1.0 if a.lower() == b.lower() else 0.0
    return len(ta & tb) / max(1, len(ta | tb))


def search_det(ao, target, max_l1: int = 4000, max_d2: int = 60000, wall_s: float = 150.0):
    """Breadth-first typed-repair search (depth <= 2), identical operator set to repair_census.search, but with a
    deterministic candidate budget. Returns (ops | None, n_equiv_timeouts, wall_hit)."""
    ft = fp(target)
    t0 = time.time()
    lvl1, seen = [], set()
    n_to = 0
    for lab, c in edits(ao, target):
        s = str(c)
        if s in seen:
            continue
        seen.add(s)
        if len(lvl1) < max_l1:
            lvl1.append((lab, c))
        if fp(c) == ft:
            r = equivalent(c, target, ms=1500)
            if r is True:
                return [lab], n_to, False
            if r is None:
                n_to += 1
    n = 0
    for lab1, c1 in lvl1:
        for lab2, c2 in edits(c1, target):
            n += 1
            if lab1 == "NEG" and lab2 == "NEG":
                continue
            if n > max_d2:
                return None, n_to, False
            if (n & 255) == 0 and time.time() - t0 > wall_s:
                return None, n_to, True
            if fp(c2) == ft:
                r = equivalent(c2, target, ms=1500)
                if r is True:
                    return sorted([lab1, lab2]), n_to, False
                if r is None:
                    n_to += 1
    return None, n_to, False


def equivalent_modulo_vocab(cand_str: str | None, ref_str: str, ms: int = 5000, do_search: bool = True) -> dict:
    """Classify a candidate against a reference.

    cls in {EQUIV, VOCAB, GRAN, ERROR, COMPOUND, TIMEOUT_UNKNOWN, UNPARSEABLE, REF_UNPARSEABLE}.
    VOCAB: equivalent after predicate/constant renaming (same arity) by the iter-3 aligner.
    GRAN: equivalent after a merge/split/reification definitional bridge.
    ERROR: a typed repair of depth <= 2 exists (ops = operator labels).
    COMPOUND: no repair within depth 2 (includes many vocabulary/granularity mismatches the aligner misses).
    TIMEOUT_UNKNOWN: every equivalence check timed out (never merged with EQUIV/UNSAT).
    """
    if cand_str is None or not str(cand_str).strip():
        return {"cls": "UNPARSEABLE", "why": "empty"}
    try:
        ref = parse(ref_str)
    except Exception as e:  # noqa: BLE001 - grammar errors are data, not bugs
        return {"cls": "REF_UNPARSEABLE", "why": str(e)[:120]}
    try:
        c = parse(cand_str)
    except Exception as e:  # noqa: BLE001
        return {"cls": "UNPARSEABLE", "why": str(e)[:120]}
    timeouts = 0
    try:
        r = equivalent(c, ref, ms)
    except Exception as e:  # noqa: BLE001 - z3 conversion failure (e.g. same name used as predicate and constant)
        return {"cls": "UNPARSEABLE", "why": "z3:" + str(e)[:100]}
    if r is True:
        return {"cls": "EQUIV"}
    if r is None:
        timeouts += 1
    ao, pmap, cmap = align(c, ref)
    renames = [(f"{k[0]}", v) for k, v in pmap.items()] + list(cmap.items())
    borderline = any(token_jaccard(p, q) < 0.5 for p, q in renames)
    pm = {f"{k[0]}/{k[1]}": v for k, v in pmap.items()}
    r = equivalent(ao, ref, ms)
    if r is True:
        return {"cls": "VOCAB", "pmap": pm, "cmap": cmap, "borderline": borderline}
    if r is None:
        timeouts += 1
    gb = gran_bridge(ao, ref)
    if gb:
        r = equivalent(gb[0], gb[1], ms)
        if r is True:
            return {"cls": "GRAN", "pmap": pm, "cmap": cmap, "borderline": True}
        if r is None:
            timeouts += 1
    if not do_search:
        return {"cls": "NONEQUIV_NOSEARCH", "pmap": pm, "cmap": cmap}
    base, tgt = (gb if gb else (ao, ref))
    ops, n_to, wall_hit = search_det(base, tgt)
    if ops:
        return {"cls": "ERROR", "ops": ops, "depth": len(ops), "pmap": pm, "cmap": cmap}
    n_calls = 3 if gb else 2
    if timeouts >= n_calls:  # every pre-search equivalence call timed out
        return {"cls": "TIMEOUT_UNKNOWN", "pmap": pm, "cmap": cmap}
    return {"cls": "COMPOUND", "pmap": pm, "cmap": cmap, "search_wall_hit": wall_hit, "search_equiv_timeouts": n_to}


def parse_ok(fol_str: str | None) -> bool:
    """Parses with the shared grammar AND converts to z3."""
    if fol_str is None:
        return False
    try:
        e = parse(fol_str)
        equivalent(e, e, 1000)
        return True
    except Exception:  # noqa: BLE001
        return False


def ast_depth(e) -> int:
    k = e[0]
    if k == "atom":
        return 1
    if k in ("all", "ex"):
        return 1 + ast_depth(e[2])
    if k == "not":
        return 1 + ast_depth(e[1])
    return 1 + max(ast_depth(e[1]), ast_depth(e[2]))


def n_quantifiers(e) -> int:
    k = e[0]
    if k == "atom":
        return 0
    if k in ("all", "ex"):
        return 1 + n_quantifiers(e[2])
    if k == "not":
        return n_quantifiers(e[1])
    return n_quantifiers(e[1]) + n_quantifiers(e[2])


def _conjuncts(e) -> int:
    return _conjuncts(e[1]) + _conjuncts(e[2]) if e[0] == "and" else 1


def n_conditions(e) -> int:
    """Number of conjuncts in the antecedents of → (and in ∀-restrictors, which are → antecedents in FOLIO notation)."""
    k = e[0]
    if k == "atom":
        return 0
    if k in ("all", "ex"):
        return n_conditions(e[2])
    if k == "not":
        return n_conditions(e[1])
    own = _conjuncts(e[1]) if k == "imp" else 0
    return own + n_conditions(e[1]) + n_conditions(e[2])


EXC_RE = re.compile(r"\b(unless|except|excluding|other than|apart from|but not|without)\b", re.I)

src_files.src/labeller/repair_census.py:
"""MINIMAL-TYPED-REPAIR census of real NL->FOL errors (review critique 1 & 2 of iter 2).

For every curated FOLIO-conclusion / MALLS-test item whose ORIGINAL gold is not logically equivalent to the
CORRECTED gold (arXiv 2606.02837, HF DSAVlab-UNIUD), we ask: what is the SMALLEST sequence of typed edits that
turns the original into a formula equivalent to the corrected one, AFTER vocabulary alignment?

Stage 0  ALIGN   rename original predicates/constants onto corrected ones (same arity; CamelCase-token Jaccard
                 >= 0.5 or char-trigram Dice >= 0.6; constants by normalised string / containment).
                 equivalent after renaming                 -> VOCAB   (vocabulary only; not an error)
Stage 1  GRAN    definitional merge/split bridge: P(args) := Q1(args) & Q2(args) when tokens(P) == tokens(Q1)+tokens(Q2)
                 equivalent after bridge                   -> GRAN    (granularity only; not an error)
Stage 2  REPAIR  breadth-first search, depth <= 2, over typed operators applied to the aligned original:
                 NEG (insert/remove negation), REV (swap sides of ->), QUANT (forall<->exists), RESTR (-> <-> & directly
                 under a quantifier), CONN (other connective change among & | -> <-> xor), DROP (delete an operand of & / |),
                 ADD (conjoin an atom that exists only in the corrected formula), SWAP (permute arguments),
                 BIND (replace one argument by another in-scope variable or a corrected-formula constant),
                 SCOPE (swap adjacent quantifiers), UNGLUE (split independent generic claims out of one quantifier block).
                 A candidate is accepted when z3 proves it equivalent to the corrected formula; a cheap random-model
                 fingerprint pre-filters candidates. Items with no repair within depth 2 are COMPOUND.
The class of a real error is its operator multiset. Curators' AMBIGUITY flag is carried along, so 'reading choice'
corrections can be reported separately.
"""
import itertools
import json
import random
import re
import sys
import time
from collections import Counter
from pathlib import Path

from .fol import parse, equivalent

D = Path(__file__).resolve().parent.parent / "data"
TOKRE = re.compile(r"[A-Z]?[a-z]+|[A-Z]+(?![a-z])|\d+")
STOP = {"and", "or", "of", "in", "on", "the", "a", "an", "to", "is", "has", "have", "can", "for", "with", "by", "at", "from", "be", "are"}
BIN = ("and", "or", "imp", "iff", "xor")


def toks(name):
    out = []
    for w in TOKRE.findall(name.replace("_", " ")):
        w = w.lower()
        if w in STOP:
            continue
        out.append(w[:-1] if w.endswith("s") and len(w) > 3 else w)
    return out


def tri(s):
    s = re.sub(r"[^a-z0-9]", "", s.lower())
    return {s[i:i + 3] for i in range(max(1, len(s) - 2))}


def dice(a, b):
    A, B = tri(a), tri(b)
    return 2 * len(A & B) / max(1, len(A) + len(B))


# ---------------------------------------------------------------- AST utilities
def atoms(e, acc=None):
    acc = [] if acc is None else acc
    if e[0] == "atom":
        acc.append(e)
    elif e[0] in ("all", "ex"):
        atoms(e[2], acc)
    elif e[0] == "not":
        atoms(e[1], acc)
    else:
        atoms(e[1], acc); atoms(e[2], acc)
    return acc


def bound_vars(e, acc=None):
    acc = set() if acc is None else acc
    if e[0] in ("all", "ex"):
        acc.add(e[1]); bound_vars(e[2], acc)
    elif e[0] == "not":
        bound_vars(e[1], acc)
    elif e[0] != "atom":
        bound_vars(e[1], acc); bound_vars(e[2], acc)
    return acc


def symbols(e):
    bv = bound_vars(e)
    P, C = {}, set()
    for a in atoms(e):
        P[(a[1], len(a[2]))] = True
        for x in a[2]:
            if x not in bv:
                C.add(x)
    return set(P), C


def rename(e, pmap, cmap, bv=frozenset()):
    k = e[0]
    if k == "atom":
        return ("atom", pmap.get((e[1], len(e[2])), e[1]), tuple(x if x in bv else cmap.get(x, x) for x in e[2]))
    if k in ("all", "ex"):
        return (k, e[1], rename(e[2], pmap, cmap, bv | {e[1]}))
    if k == "not":
        return ("not", rename(e[1], pmap, cmap, bv))
    return (k, rename(e[1], pmap, cmap, bv), rename(e[2], pmap, cmap, bv))


def expand(e, defs):
    """defs: {(name, arity): [name1, name2]}  P(args) -> Q1(args) & Q2(args)"""
    k = e[0]
    if k == "atom":
        key = (e[1], len(e[2]))
        if key in defs:
            q = defs[key]
            out = ("atom", q[0], e[2])
            for n in q[1:]:
                out = ("and", out, ("atom", n, e[2]))
            return out
        return e
    if k in ("all", "ex"):
        return (k, e[1], expand(e[2], defs))
    if k == "not":
        return ("not", expand(e[1], defs))
    return (k, expand(e[1], defs), expand(e[2], defs))


def align(old, new):
    Po, Co = symbols(old)
    Pn, Cn = symbols(new)
    pmap, used = {}, set()
    cands = []
    for p in Po - Pn:
        for q in Pn - Po:
            if p[1] != q[1]:
                continue
            to, tn = set(toks(p[0])), set(toks(q[0]))
            j = len(to & tn) / max(1, len(to | tn))
            s = max(j, dice(p[0], q[0]))
            if p[0].lower() == q[0].lower():
                s = 2
            if j >= 0.5 or dice(p[0], q[0]) >= 0.6 or s == 2:
                cands.append((s, p, q))
    for s, p, q in sorted(cands, reverse=True):
        if p in pmap or q in used:
            continue
        pmap[p] = q[0]; used.add(q)
    cmap, cused = {}, set()
    norm = lambda s: re.sub(r"[^a-z0-9]", "", s.lower())
    for c in Co - Cn:
        best = None
        for d in Cn - Co:
            if d in cused:
                continue
            a, b = norm(c), norm(d)
            if a == b or (min(len(a), len(b)) >= 4 and (a in b or b in a)) or dice(c, d) >= 0.7:
                best = d
                break
        if best:
            cmap[c] = best; cused.add(best)
    return rename(old, pmap, cmap), pmap, cmap


def gran_bridge(ao, new):
    """Try merge/split definitional bridges between leftover predicates of the aligned original and corrected."""
    Po, _ = symbols(ao)
    Pn, _ = symbols(new)
    lo, ln = Po - Pn, Pn - Po
    defs_old, defs_new = {}, {}
    for p in lo:  # original merged predicate -> corrected split pair
        tp = sorted(toks(p[0]))
        for q1, q2 in itertools.combinations([q for q in ln if q[1] == p[1]], 2):
            if sorted(toks(q1[0]) + toks(q2[0])) == tp or set(toks(q1[0]) + toks(q2[0])) == set(tp):
                defs_old[p] = [q1[0], q2[0]]
    for q in ln:  # corrected merged predicate -> original split pair
        tq = sorted(toks(q[0]))
        for p1, p2 in itertools.combinations([p for p in lo if p[1] == q[1]], 2):
            if sorted(toks(p1[0]) + toks(p2[0])) == tq or set(toks(p1[0]) + toks(p2[0])) == set(tq):
                defs_new[q] = [p1[0], p2[0]]
    _, Cn = symbols(new)
    reify = {}
    for p in lo:  # P(x) := Q(x, c) when tokens(P) == tokens(Q) + tokens(c)
        for q in ln:
            if q[1] != p[1] + 1:
                continue
            for c in Cn:
                if set(toks(q[0]) + toks(c)) == set(toks(p[0])):
                    reify[p] = (q[0], c)
    if not defs_old and not defs_new and not reify:
        return None
    return reify_expand(expand(ao, defs_old), reify), expand(new, defs_new)


def reify_expand(e, reify):
    k = e[0]
    if k == "atom":
        key = (e[1], len(e[2]))
        if key in reify:
            q, c = reify[key]
            return ("atom", q, e[2] + (c,))
        return e
    if k in ("all", "ex"):
        return (k, e[1], reify_expand(e[2], reify))
    if k == "not":
        return ("not", reify_expand(e[1], reify))
    return (k, reify_expand(e[1], reify), reify_expand(e[2], reify))


# ---------------------------------------------------------------- random-model fingerprint (necessary condition)
SEEDS = list(range(24))


def ev(e, m, env, dom, seed):
    k = e[0]
    if k == "atom":
        args = tuple(env[x] if x in env else (hash((seed, "c", x)) % dom) for x in e[2])
        return (hash((seed, e[1], len(e[2]), args)) >> 3) & 1 == 1
    if k == "all":
        return all(ev(e[2], m, {**env, e[1]: d}, dom, seed) for d in range(dom))
    if k == "ex":
        return any(ev(e[2], m, {**env, e[1]: d}, dom, seed) for d in range(dom))
    if k == "not":
        return not ev(e[1], m, env, dom, seed)
    a, b = ev(e[1], m, env, dom, seed), ev(e[2], m, env, dom, seed)
    return {"and": a and b, "or": a or b, "imp": (not a) or b, "iff": a == b, "xor": a != b}[k]


def fp(e):
    return tuple(ev(e, None, {}, 3, s) for s in SEEDS)


# ---------------------------------------------------------------- typed operators
def subterms(e, path=(), scope=()):
    yield path, e, scope
    k = e[0]
    if k in ("all", "ex"):
        yield from subterms(e[2], path + (2,), scope + (e[1],))
    elif k == "not":
        yield from subterms(e[1], path + (1,), scope)
    elif k != "atom":
        yield from subterms(e[1], path + (1,), scope)
        yield from subterms(e[2], path + (2,), scope)


def replace(e, path, new):
    if not path:
        return new
    i = path[0]
    lst = list(e)
    lst[i] = replace(e[i], path[1:], new)
    return tuple(lst)


def parent_kind(e, path):
    if not path:
        return None
    x = e
    for i in path[:-1]:
        x = x[i]
    return x[0]


def unglue(node):
    """∀x∀y (A(x) ∧ B(y) → C(x) ∧ D(y))  ->  ∀x (A(x) → C(x)) ∧ ∀y (B(y) → D(y))"""
    vs, body = [], node
    while body[0] == "all":
        vs.append(body[1]); body = body[2]
    if len(vs) < 2 or body[0] != "imp":
        return None

    def conj(x):
        return conj(x[1]) + conj(x[2]) if x[0] == "and" else [x]

    def vars_of(x):
        return {a for at in atoms(x) for a in at[2] if a in vs}
    ant, con = conj(body[1]), conj(body[2])
    groups = []
    for v in vs:
        a = [x for x in ant if vars_of(x) == {v}]
        c = [x for x in con if vars_of(x) == {v}]
        if not c:
            return None
        groups.append((v, a, c))
    if sum(len(g[1]) for g in groups) != len(ant) or sum(len(g[2]) for g in groups) != len(con):
        return None

    def mk(lst, op="and"):
        out = lst[0]
        for x in lst[1:]:
            out = (op, out, x)
        return out
    parts = [("all", v, ("imp", mk(a), mk(c)) if a else mk(c)) for v, a, c in groups]
    return mk(parts)


def edits(e, target):
    """Yield (op_label, candidate) for every single typed edit of e."""
    tgt_atoms = atoms(target)
    Pe, _ = symbols(e)
    _, Ct = symbols(target)
    new_atoms = [a for a in tgt_atoms if (a[1], len(a[2])) not in Pe]
    for path, node, scope in list(subterms(e)):
        k = node[0]
        # NEG
        if k == "not":
            yield "NEG", replace(e, path, node[1])
        else:
            yield "NEG", replace(e, path, ("not", node))
        if k in ("all", "ex"):
            yield "QUANT", replace(e, path, ("ex" if k == "all" else "all", node[1], node[2]))
            # block flip with the restrictor convention: ∀x∀y(A→B) <-> ∃x∃y(A∧B)
            vs, body = [], node
            while body[0] == k:
                vs.append(body[1]); body = body[2]
            if body[0] in ("imp", "and"):
                nb = ("and" if body[0] == "imp" else "imp", body[1], body[2])
                q = "ex" if k == "all" else "all"
                for v in reversed(vs):
                    nb = (q, v, nb)
                yield "QUANT", replace(e, path, nb)
            if node[2][0] in ("all", "ex"):
                inner = node[2]
                yield "SCOPE", replace(e, path, (inner[0], inner[1], (k, node[1], inner[2])))
            ug = unglue(node) if k == "all" else None
            if ug is not None:
                yield "UNGLUE", replace(e, path, ug)
        if k in ("imp", "iff") and node[1][0] == "and":
            # MOVE: pull a conjunct of the left side out as an outer restriction: (A ∧ B op C) -> (A -> (B op C))
            yield "MOVE", replace(e, path, ("imp", node[1][1], (k, node[1][2], node[2])))
            yield "MOVE", replace(e, path, ("imp", node[1][2], (k, node[1][1], node[2])))
        if k == "imp" and node[2][0] == "imp":
            # MOVE inverse: A -> (B -> C)  <->  (A ∧ C) -> B style condition/consequence exchange
            yield "MOVE", replace(e, path, ("imp", ("and", node[1], node[2][2]), node[2][1]))
        if k in BIN:
            if k == "imp":
                yield "REV", replace(e, path, ("imp", node[2], node[1]))
            for op in BIN:
                if op != k:
                    lab = "RESTR" if {k, op} == {"imp", "and"} and parent_kind(e, path) in ("all", "ex") else "CONN"
                    yield lab, replace(e, path, (op, node[1], node[2]))
            if k in ("and", "or"):
                yield "DROP", replace(e, path, node[1])
                yield "DROP", replace(e, path, node[2])
        if k == "atom":
            args = node[2]
            if len(args) >= 2:
                for perm in set(itertools.permutations(args)):
                    if perm != args:
                        yield "SWAP", replace(e, path, ("atom", node[1], perm))
            pool = set(scope) | Ct
            for i, a in enumerate(args):
                for b in pool:
                    if b != a:
                        yield "BIND", replace(e, path, ("atom", node[1], args[:i] + (b,) + args[i + 1:]))
        # ADD: conjoin a corrected-only atom (args re-bound to in-scope variables when its variables are foreign)
        if k != "atom" or True:
            for a in new_atoms:
                sc = list(scope)
                opts = []
                for x in a[2]:
                    opts.append([x] if (x in Ct or x in sc) else (sc or [x]))
                for combo in itertools.islice(itertools.product(*opts), 6):
                    yield "ADD", replace(e, path, ("and", node, ("atom", a[1], tuple(combo))))


def search(ao, target, budget_s=25.0, max_d2=6000):
    ft = fp(target)
    t0 = time.time()
    lvl1 = []
    seen = set()
    for lab, c in edits(ao, target):
        s = str(c)
        if s in seen:
            continue
        seen.add(s)
        lvl1.append((lab, c))
        if fp(c) == ft and equivalent(c, target, ms=1500) is True:
            return [lab], time.time() - t0
    n = 0
    for lab1, c1 in lvl1:
        for lab2, c2 in edits(c1, target):
            n += 1
            if lab1 == "NEG" and lab2 == "NEG":
                continue
            if n > max_d2 * 10 or time.time() - t0 > budget_s:
                return None, time.time() - t0
            if fp(c2) == ft and equivalent(c2, target, ms=1500) is True:
                return sorted([lab1, lab2]), time.time() - t0
    return None, time.time() - t0


def load(p):
    return [json.loads(l) for l in open(p) if l.strip()]


def pairs():
    for r in load(D / "DSAVlab-UNIUD_MALLS_test_subset-CURATED__MALLS_instances.jsonl"):
        yield "MALLS", r["id"], r["NL_sentence"], r["FOL_sentence_old"], r["FOL_sentence_new"], str(r.get("ambiguity", "NA"))
    for r in load(D / "DSAVlab-UNIUD_FOLIO_validation-curated__FOLIO_instances.jsonl"):
        if str(r["id"]).startswith("story"):
            continue
        yield "FOLIO-concl", r["id"], r["NL_sentence"], r["FOL_sentence_old"], r["FOL_sentence"], str(r.get("ambiguity", "NA"))


def work(item):
    src, iid, nl, old, new, amb = item
    try:
        oe, ne = parse(old), parse(new)
    except Exception:
        return None
    if equivalent(oe, ne) is True:
        return None
    ao, pmap, cmap = align(oe, ne)
    rec = {"src": src, "id": iid, "nl": nl, "old": old, "new": new, "ambiguous": amb == "True",
           "pmap": {f"{k[0]}/{k[1]}": v for k, v in pmap.items()}, "cmap": cmap}
    if equivalent(ao, ne) is True:
        rec["cls"] = "VOCAB"; return rec
    gb = gran_bridge(ao, ne)
    if gb and equivalent(gb[0], gb[1]) is True:
        rec["cls"] = "GRAN"; return rec
    base, tgt = (gb if gb else (ao, ne))
    ops, dt = search(base, tgt)
    rec["secs"] = round(dt, 1)
    rec["cls"] = "+".join(ops) if ops else "COMPOUND"
    rec["depth"] = len(ops) if ops else None
    return rec


def main():
    from multiprocessing import Pool
    items = list(pairs())
    with Pool(2) as pool:
        recs = [r for r in pool.imap_unordered(work, items, chunksize=1) if r]
    out = Path(__file__).with_suffix(".rows.json")
    out.write_text(json.dumps(recs, ensure_ascii=False, indent=1))
    n = len(recs)
    c = Counter(r["cls"] for r in recs)
    print(f"non-equivalent pairs: {n}")
    for k, v in c.most_common():
        print(f"  {k:22s} {v:3d}  ({v/n:.2f})")
    vocab = sum(r["cls"] in ("VOCAB", "GRAN") for r in recs)
    err = [r for r in recs if r["cls"] not in ("VOCAB", "GRAN")]
    single = sum(r.get("depth") == 1 for r in err)
    two = sum(r.get("depth") == 2 for r in err)
    comp = sum(r["cls"] == "COMPOUND" for r in err)
    print(f"vocabulary/granularity-only (auto): {vocab}/{n}")
    print(f"remaining errors: {len(err)}  single-op: {single}  two-op: {two}  compound(>2 or unresolved): {comp}")
    ops = Counter(o for r in err if r.get("depth") for o in r["cls"].split("+"))
    print("operator mass among repaired errors:", dict(ops.most_common()))
    for amb in (True, False):
        sub = [r for r in recs if r["ambiguous"] == amb]
        print(f"ambiguous={amb}: n={len(sub)}", dict(Counter(r["cls"] for r in sub).most_common()))
    for s in ("MALLS", "FOLIO-concl"):
        sub = [r for r in recs if r["src"] == s]
        print(f"{s}: n={len(sub)}", dict(Counter(r["cls"] for r in sub).most_common()))


if __name__ == "__main__":
    sys.setrecursionlimit(10000)
    main()

